{
  "name": "opencode-snippets",
  "version": "3.4.0",
  "description": "Hashtag-based snippet expansion plugin for OpenCode - instant inline text shortcuts",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "default": "./dist/tui.js"
    }
  },
  "type": "module",
  "engines": {
    "node": ">=20"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "snippets",
    "templates",
    "shortcuts",
    "ai",
    "coding-assistant"
  ],
  "author": "JosXa <info@josxa.dev>",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/JosXa/opencode-snippets.git"
  },
  "bugs": {
    "url": "https://github.com/JosXa/opencode-snippets/issues"
  },
  "homepage": "https://github.com/JosXa/opencode-snippets#readme",
  "dependencies": {
    "@opencode-ai/plugin-v1": "npm:@opencode-ai/plugin@1.18.29",
    "@opencode/plugin": "2.0.12",
    "effect": "4.0.0-rc.112",
    "gray-matter": "^4.0.3",
    "handlebars": "^4.7.9",
    "jsonc-parser": "^3.3.1"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.1.99",
    "@opentui/solid": ">=0.1.99",
    "solid-js": "1.9.12"
  },
  "devDependencies": {
    "@biomejs/biome": "2.3.11",
    "@cucumber/cucumber": "^13.2.1",
    "@opencode/theme": "2.0.12",
    "@opentui/core": "0.5.10",
    "@opentui/keymap": "0.5.10",
    "@opentui/solid": "0.5.10",
    "@types/bun": "^1.4.2",
    "@types/node": "^22",
    "husky": "^9.1.7",
    "solid-js": "1.9.12",
    "typescript": "^7.0.2"
  },
  "scripts": {
    "build": "bun scripts/build.ts",
    "test:v1": "bun run build && SNIPPETS_TEST_V1=1 bun test ./tests/v1-runtime.test.ts",
    "test:v2": "bun run build && SNIPPETS_TEST_V2=1 bun test ./tests/*.test.ts",
    "test:tui": "bun run build && bun tests/tui-playground.ts",
    "test:bdd": "bun --conditions=browser --preload @opentui/solid/preload ./tests/bdd/run.ts",
    "typecheck": "tsc --noEmit",
    "typecheck:bdd": "tsc --noEmit -p tests/bdd/tsconfig.json",
    "format:check": "biome check .",
    "format:fix": "biome check --write .",
    "ai:check": "biome check --write --error-on-warnings . && tsc --noEmit",
    "prepare": "node scripts/prepare.mjs",
    "prepublishOnly": "bun run build"
  },
  "files": ["dist", "scripts/prepare.mjs", "skill", "tui", "examples/forms"],
  "directories": {
    "doc": "docs"
  }
}

{
  "type": "module",
  "main": "./index.js"
}
